from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]

        dp = {}
        left, right = 0, n - 1
        for a, b in pairs:
            dp[(a, b)] = cost[left][a] + cost[right][b]

        for i in range(1, n // 2):
            left, right = i, n - 1 - i
            ndp = {}
            for a, b in pairs:
                cur_cost = cost[left][a] + cost[right][b]
                best = INF
                for pa, pb in pairs:
                    if a != pa and b != pb:
                        v = dp[(pa, pb)] + cur_cost
                        if v < best:
                            best = v
                ndp[(a, b)] = best
            dp = ndp

        return min(dp.values())
